// Column conventions shared by every table (ADR-0004).
import { sql } from 'drizzle-orm';
import { timestamp, uuid } from 'drizzle-orm/pg-core';

/** UUIDv7 primary key generated by PostgreSQL 18, so ids sort by creation time. */
export const primaryId = () => uuid('id').primaryKey().default(sql`uuidv7()`);

/** Timestamps are always `timestamptz` (stored in UTC). */
export const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
